from pathlib import Path
from playwright.sync_api import sync_playwright
import base64,re,json
p=Path(__file__).resolve().parent.parent
s=(p/'island-preview.html').read_text();s=s.replace('<link rel="stylesheet" href="data/island-ui.css">','<style>'+(p/'data/island-ui.css').read_text()+'</style>');s=s.replace('<script src="data/island-art.js"></script>','<script>'+(p/'data/island-art.js').read_text()+'</script>')
for f in ['source','core','names','locales','ui']:s=s.replace(f'<script src="data/island-{f}.js"></script>','<script>'+(p/f'data/island-{f}.js').read_text()+'</script>')
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':393,'height':852},device_scale_factor=1);errors=[];page.on('pageerror',lambda e: errors.append(str(e)));page.set_content(s)
 checks=page.evaluate('''()=>{let screens=0,interactions=0,localeChecks=0;const bad=[];const test=(message,fn)=>{try{if(!fn())bad.push(message)}catch(e){bad.push(message+': '+e.message)}};const el=()=>document.getElementById('islandRoot');const check=(name)=>{screens++;test(name+' content',()=>!(/\\b(?:undefined|NaN|Infinity)\\b/.test(el().textContent))&&el().textContent.trim().length>0)};const choose=(node,value)=>{node.value=String(value);node.dispatchEvent(new Event('change'));interactions++};for(const l of Object.keys(IslandUI.words)){language.value=l;language.onchange();for(const id of ['home','port','portplan','land','sea','sets']){island.go(id);check(l+' '+id);if(id==='portplan'){const a=el().querySelectorAll('.is-port-plan select');test(l+' port plan fields',()=>a.length===8);choose(a[1],-1);test(l+' port requirements',()=>el().textContent.includes(IslandUI.words[l].needLevel));choose(a[1],59);check(l+' port full')}if(id==='land'){const q=el().querySelector('.is-search');q.value='zzzzzzzz';q.dispatchEvent(new Event('input'));test(l+' empty search',()=>el().querySelector('.is-grid').textContent.includes(IslandUI.words[l].empty));interactions++;q.value='';q.dispatchEvent(new Event('input'));test(l+' 80 land',()=>el().querySelectorAll('.is-card').length===80);interactions++}}
for(const x of [...islandSource1724.deco,...Object.keys(islandSource1724.dock).map(id=>({id:Number(id),rows:islandSource1724.dock[id],type:'dock'}))]){island.go('detail',x.id);check(l+' '+x.id);const fields=el().querySelectorAll('.is-fields select');if(x.rows.length){test(l+' fields '+x.id,()=>fields.length===2);if(fields.length===2){choose(fields[0],x.rows.length-1);choose(fields[1],x.rows.length-1);test(l+' max '+x.id,()=>!el().textContent.includes('NaN'));choose(fields[0],x.type==='sea'||x.type==='dock'?-1:0);choose(fields[1],x.rows.length-1);check(l+' full '+x.id)}}else{test(l+' simple '+x.id,()=>fields.length===0)}}
for(let id=1;id<=6;id++){island.go('set',id);check(l+' set '+id);const s=el().querySelectorAll('.is-set-member select');test(l+' members '+id,()=>s.length===5);for(const n of s)choose(n,14);check(l+' set max '+id);choose(s[0],-1);test(l+' set inactive '+id,()=>el().textContent.includes(IslandUI.words[l].notActive));check(l+' set inactive '+id)}localeChecks++}island.go('home');return {screens,interactions,localeChecks,bad:bad.slice(0,30),badCount:bad.length}}''');print(json.dumps(checks,ensure_ascii=False), 'errors',errors)
 # Functional-only pass; art and layout are checked separately.
